import os
for r,d,f in os.walk('studies'):
    for x in f: print(os.path.join(r,x), os.path.getsize(os.path.join(r,x)))

import gzip,glob
for f in sorted(glob.glob('studies/data/raw/*series_matrix*')):
    print('=====',f)
    for l in gzip.open(f,'rt',errors='ignore'):
        if l.startswith('!series_matrix_table_begin'): break
        if l.startswith(('!Sample_title','!Sample_source','!Sample_characteristics','!Sample_geo_accession')):
            print(l[:1500].rstrip())

import gzip,glob,collections
for f in sorted(glob.glob('studies/data/raw/*series_matrix*')):
    print('=====',f)
    rows={}
    for l in gzip.open(f,'rt',errors='ignore'):
        if l.startswith('!series_matrix_table_begin'): break
        if l.startswith('!Sample_'):
            p=l.rstrip('\n').split('\t'); k=p[0]
            while k in rows: k+='_'
            rows[k]=[x.strip('"') for x in p[1:]]
    n=len(rows['!Sample_geo_accession']); print('n=',n)
    for k,v in rows.items():
        c=collections.Counter(v)
        if len(c)<=12 and k not in('!Sample_data_processing',): print(k,dict(c))
    if n<60: print(rows['!Sample_title'])

